const form=document.querySelector('#login-form'),error=document.querySelector('#login-error'),button=form.querySelector('button');
form.addEventListener('submit',async e=>{e.preventDefault();error.textContent='';button.disabled=true;button.textContent='正在登录…';try{const response=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({username:document.querySelector('#username').value,password:document.querySelector('#password').value})});const result=await response.json();if(!response.ok)throw Error(typeof result.detail==='string'?result.detail:'登录失败，请核对输入。');location.assign('/')}catch(e){error.textContent=e.message}finally{button.disabled=false;button.textContent='登录'}});
